using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using Microsoft.AspNetCore.Identity;
namespace WudilFood.Models;
public static class Roles { public const string Customer="Customer",Vendor="Vendor",Admin="Admin"; }
public class AppUser : IdentityUser { [MaxLength(100)] public string FullName {get;set;}=""; [MaxLength(240)] public string? Address {get;set;} public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; }
public enum ApprovalStatus { Pending=0, Approved=1, Rejected=2, Suspended=3 }
public class Vendor { public int Id {get;set;} public string UserId {get;set;}=""; public AppUser User {get;set;}=null!; [MaxLength(120)] public string Name {get;set;}=""; [MaxLength(500)] public string Description {get;set;}=""; [MaxLength(120)] public string Location {get;set;}=""; [MaxLength(100)] public string OperatingHours {get;set;}=""; public ApprovalStatus Status {get;set;}=ApprovalStatus.Pending; public ICollection<MenuItem> Items {get;set;}=new List<MenuItem>(); public ICollection<VendorClosure> Closures {get;set;}=new List<VendorClosure>(); }
public class VendorClosure { public int Id {get;set;} public int VendorId {get;set;} public Vendor Vendor {get;set;}=null!; public DateTime StartsUtc {get;set;} public DateTime EndsUtc {get;set;} [MaxLength(200)] public string Reason {get;set;}=""; }
public class Category { public int Id {get;set;} [MaxLength(80)] public string Name {get;set;}=""; }
public enum AvailabilityMode { Immediate, Preorder, Unavailable }
public class MenuItem { public int Id {get;set;} public int VendorId {get;set;} public Vendor Vendor {get;set;}=null!; public int CategoryId {get;set;} public Category Category {get;set;}=null!; [MaxLength(120)] public string Name {get;set;}=""; [MaxLength(600)] public string Description {get;set;}=""; [Range(1,10000000)] public decimal Price {get;set;} public int Stock {get;set;} public int PreparationMinutes {get;set;}=30; public string? ImageUrl {get;set;} [NotMapped] public IReadOnlyList<string> ImageUrls=>string.IsNullOrWhiteSpace(ImageUrl)?Array.Empty<string>():ImageUrl.Split('|',StringSplitOptions.RemoveEmptyEntries); [NotMapped] public string? PrimaryImage=>ImageUrls.FirstOrDefault(); public bool IsVisible {get;set;}=true; public AvailabilityMode Mode {get;set;}=AvailabilityMode.Immediate; public ICollection<FoodSchedule> Schedules {get;set;}=new List<FoodSchedule>(); }
public class FoodSchedule { public int Id {get;set;} public int MenuItemId {get;set;} public MenuItem MenuItem {get;set;}=null!; public DayOfWeek Day {get;set;} public TimeOnly StartsAt {get;set;} public TimeOnly EndsAt {get;set;} public TimeOnly OrderDeadline {get;set;} public int? Capacity {get;set;} }
public class Rider { public int Id {get;set;} [MaxLength(100)] public string Name {get;set;}=""; [MaxLength(30)] public string PhoneNumber {get;set;}=""; public bool IsActive {get;set;}=true; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public ICollection<FoodOrder> Orders {get;set;}=new List<FoodOrder>(); }
public enum Fulfillment { Delivery=0, SelfPickup=1, VendorCollection=3 }
public enum OrderState { Pending=0, Accepted=1, Processing=2, Preparing=2, Ready=3, Shipped=4, OutForDelivery=4, Delivered=5, Cancelled=6, Completed=7 }
public enum PaymentMethod { Cash, BankTransfer, PayOnCollection }
public enum PaymentState { Unpaid, PendingVerification, Paid }
public class FoodOrder { public int Id {get;set;} public string Reference {get;set;}=""; public string CustomerId {get;set;}=""; public AppUser Customer {get;set;}=null!; public int VendorId {get;set;} public Vendor Vendor {get;set;}=null!; public int? RiderId {get;set;} public Rider? Rider {get;set;} public DateTime SlotUtc {get;set;} public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public Fulfillment Fulfillment {get;set;} public OrderState State {get;set;}=OrderState.Pending; public PaymentMethod PaymentMethod {get;set;} public PaymentState PaymentState {get;set;}=PaymentState.Unpaid; public decimal ItemsTotal {get;set;} public decimal DeliveryFee {get;set;} public decimal Total => ItemsTotal+DeliveryFee; public string? DeliveryAddress {get;set;} public string? Note {get;set;} public List<OrderLine> Lines {get;set;}=new(); public Review? Review {get;set;} }
public class OrderStatusHistory { public int Id {get;set;} public int FoodOrderId {get;set;} public FoodOrder Order {get;set;}=null!; public OrderState? FromState {get;set;} public OrderState ToState {get;set;} public DateTime ChangedUtc {get;set;}=DateTime.UtcNow; [MaxLength(120)] public string ChangedBy {get;set;}="System"; }
public class OrderLine { public int Id {get;set;} public int FoodOrderId {get;set;} public FoodOrder Order {get;set;}=null!; public int MenuItemId {get;set;} public MenuItem MenuItem {get;set;}=null!; public string ItemName {get;set;}=""; public int Quantity {get;set;} public decimal UnitPrice {get;set;} }
public class Favorite { public int Id {get;set;} public string CustomerId {get;set;}=""; public AppUser Customer {get;set;}=null!; public int MenuItemId {get;set;} public MenuItem MenuItem {get;set;}=null!; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; }
public class Review { public int Id {get;set;} public int FoodOrderId {get;set;} public FoodOrder Order {get;set;}=null!; public int Rating {get;set;} public string Comment {get;set;}=""; public bool Approved {get;set;} }
public class Notice { public int Id {get;set;} public string UserId {get;set;}=""; public AppUser User {get;set;}=null!; public string Text {get;set;}=""; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; public bool Read {get;set;} }
public class Complaint { public int Id {get;set;} public int FoodOrderId {get;set;} public FoodOrder Order {get;set;}=null!; public string UserId {get;set;}=""; public string Text {get;set;}=""; public string Resolution {get;set;}=""; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; }
public class AuditLog { public int Id {get;set;} [MaxLength(80)] public string ActorId {get;set;}=""; [MaxLength(80)] public string Action {get;set;}=""; [MaxLength(80)] public string EntityType {get;set;}=""; [MaxLength(80)] public string EntityId {get;set;}=""; [MaxLength(500)] public string Details {get;set;}=""; public DateTime CreatedUtc {get;set;}=DateTime.UtcNow; }
public class PlatformSetting { public int Id {get;set;}=1; public decimal DeliveryFee {get;set;}=500; public string Coverage {get;set;}="Wudil, ADUSTECH"; public bool DeliveryEnabled {get;set;}=true; }
